# syntax=docker/dockerfile:1
# ocarina's production image: the app member (app/) is the build context. Built for amd64 and arm64
# by .github/workflows/build.yml and run from k8s/ as https://ocarina.apps.arugula.io. Written by planter
# (arugula-salad/planter prod-scaffold.mjs); edit it freely.
FROM node:22-slim
WORKDIR /srv/app
ENV NODE_ENV=production PORT=8080 HOST=0.0.0.0
COPY package*.json ./
RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force
COPY . .
# The box runs the app behind hud's proxy, so the template's server listens on 127.0.0.1. In a pod it
# must listen on every address: this preload rebinds a loopback listen to HOST. It also stops the app
# on SIGTERM when the app does not handle it (node as PID 1 ignores it), closing its servers first.
# Once the app listens on process.env.HOST itself and handles SIGTERM, drop it and NODE_OPTIONS.
COPY <<'EOF' /opt/studio/pod.cjs
'use strict';
const net = require('node:net');
const host = process.env.HOST;
const loopback = /^(127\.0\.0\.1|localhost|::1)$/;
const servers = new Set();
const listen = net.Server.prototype.listen;
net.Server.prototype.listen = function (...args) {
  if (host && typeof args[1] === 'string' && loopback.test(args[1])) args[1] = host;
  else if (host && args[0] && typeof args[0] === 'object' && loopback.test(String(args[0].host))) args[0] = { ...args[0], host };
  servers.add(this);
  return listen.apply(this, args);
};
process.on('SIGTERM', () => {
  if (process.listenerCount('SIGTERM') > 1) return;
  for (const server of servers) { server.close(); server.closeIdleConnections?.(); }
  setTimeout(() => process.exit(0), 10000).unref();
});
EOF
ENV NODE_OPTIONS=--require=/opt/studio/pod.cjs
ARG APP_REVISION=dev
ENV APP_REVISION=$APP_REVISION
# The image's node user, by number: the pod's runAsNonRoot needs a numeric user. The root filesystem
# is read-only in the pod; the app writes only /tmp.
USER 1000:1000
EXPOSE 8080
CMD ["node","server.js"]

files.k8s/platform/dashboard.yaml:
# Generated from app.yaml by arugula-salad/planter's platform-app (needs.telemetry). Don't edit: the next
# build of main renders it again. Change app.yaml, or patch it from k8s/kustomization.yaml.
# A Grafana dashboard for ocarina, "ocarina (planter-apps)": requests, errors and latency as Traefik
# sees them, the pods' memory and CPU, their logs, and the app's traces (if it sends any; see the
# OTEL_ variables in deployment.yaml). Grafana loads every ConfigMap labelled grafana_dashboard: "1".
apiVersion: v1
kind: ConfigMap
metadata:
  name: ocarina-dashboard
  labels:
    app.kubernetes.io/name: ocarina
    grafana_dashboard: "1"
data:
  ocarina.json: |
    {
      "uid": "planter-ocarina",
      "title": "ocarina (planter-apps)",
      "tags": [
        "planter-apps"
      ],
      "timezone": "browser",
      "schemaVersion": 39,
      "time": {
        "from": "now-6h",
        "to": "now"
      },
      "links": [
        {
          "title": "https://ocarina.apps.arugula.io",
          "url": "https://ocarina.apps.arugula.io",
          "type": "link",
          "targetBlank": true
        }
      ],
      "panels": [
        {
          "id": 1,
          "title": "Requests by status",
          "type": "timeseries",
          "gridPos": {
            "x": 0,
            "y": 0,
            "w": 12,
            "h": 8
          },
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "targets": [
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "sum by (code) (rate(traefik_service_requests_total{service=~\"planter-apps-ocarina-[0-9a-f]+@kubernetescrd\"}[$__rate_interval]))",
              "legendFormat": "{{code}}",
              "refId": "A"
            }
          ],
          "fieldConfig": {
            "defaults": {
              "unit": "reqps"
            },
            "overrides": []
          }
        },
        {
          "id": 2,
          "title": "Server errors",
          "type": "timeseries",
          "gridPos": {
            "x": 12,
            "y": 0,
            "w": 6,
            "h": 8
          },
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "targets": [
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "sum(rate(traefik_service_requests_total{service=~\"planter-apps-ocarina-[0-9a-f]+@kubernetescrd\", code=~\"5..\"}[$__rate_interval])) / sum(rate(traefik_service_requests_total{service=~\"planter-apps-ocarina-[0-9a-f]+@kubernetescrd\"}[$__rate_interval]))",
              "legendFormat": "5xx",
              "refId": "A"
            }
          ],
          "fieldConfig": {
            "defaults": {
              "unit": "percentunit",
              "min": 0
            },
            "overrides": []
          }
        },
        {
          "id": 3,
          "title": "Latency",
          "type": "timeseries",
          "gridPos": {
            "x": 18,
            "y": 0,
            "w": 6,
            "h": 8
          },
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "targets": [
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "histogram_quantile(0.5, sum by (le) (rate(traefik_service_request_duration_seconds_bucket{service=~\"planter-apps-ocarina-[0-9a-f]+@kubernetescrd\"}[$__rate_interval])))",
              "legendFormat": "p50",
              "refId": "A"
            },
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "histogram_quantile(0.95, sum by (le) (rate(traefik_service_request_duration_seconds_bucket{service=~\"planter-apps-ocarina-[0-9a-f]+@kubernetescrd\"}[$__rate_interval])))",
              "legendFormat": "p95",
              "refId": "B"
            }
          ],
          "fieldConfig": {
            "defaults": {
              "unit": "s"
            },
            "overrides": []
          }
        },
        {
          "id": 4,
          "title": "Memory",
          "type": "timeseries",
          "gridPos": {
            "x": 0,
            "y": 8,
            "w": 12,
            "h": 7
          },
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "targets": [
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "sum by (pod) (container_memory_working_set_bytes{namespace=\"planter-apps\", pod=~\"ocarina-[a-z0-9]+-[a-z0-9]{5}\", container=\"ocarina\"})",
              "legendFormat": "{{pod}}",
              "refId": "A"
            }
          ],
          "fieldConfig": {
            "defaults": {
              "unit": "bytes"
            },
            "overrides": []
          }
        },
        {
          "id": 5,
          "title": "CPU",
          "type": "timeseries",
          "gridPos": {
            "x": 12,
            "y": 8,
            "w": 12,
            "h": 7
          },
          "datasource": {
            "type": "prometheus",
            "uid": "prometheus"
          },
          "targets": [
            {
              "datasource": {
                "type": "prometheus",
                "uid": "prometheus"
              },
              "expr": "sum by (pod) (rate(container_cpu_usage_seconds_total{namespace=\"planter-apps\", pod=~\"ocarina-[a-z0-9]+-[a-z0-9]{5}\", container=\"ocarina\"}[$__rate_interval]))",
              "legendFormat": "{{pod}}",
              "refId": "A"
            }
          ],
          "fieldConfig": {
            "defaults": {
              "unit": "short"
            },
            "overrides": []
          }
        },
        {
          "id": 6,
          "title": "Logs",
          "type": "logs",
          "gridPos": {
            "x": 0,
            "y": 15,
            "w": 24,
            "h": 10
          },
          "datasource": {
            "type": "loki",
            "uid": "loki"
          },
          "targets": [
            {
              "datasource": {
                "type": "loki",
                "uid": "loki"
              },
              "expr": "{namespace=\"planter-apps\", app=\"ocarina\"}",
              "refId": "A"
            }
          ]
        },
        {
          "id": 7,
          "title": "Traces",
          "type": "table",
          "gridPos": {
            "x": 0,
            "y": 25,
            "w": 24,
            "h": 8
          },
          "datasource": {
            "type": "tempo",
            "uid": "tempo"
          },
          "targets": [
            {
              "datasource": {
                "type": "tempo",
                "uid": "tempo"
              },
              "queryType": "traceql",
              "query": "{resource.service.name=\"ocarina\"}",
              "limit": 20,
              "refId": "A"
            }
          ]
        }
      ]
    }
